-- =====================================================================================
-- Approval Rate Copilot | Lakeflow pipeline, Spark Declarative Pipelines (bronze -> silver -> gold)
-- Generated by tools/build_databricks.py from the SQL bodies in /sql. Do not edit by hand.
-- Data: 100% synthetic. Fictional orchestrator, acquirers (A, B, C), issuers and merchants.
-- =====================================================================================
-- Pipeline settings: default catalog `workspace`, default schema `approval_copilot`,
-- serverless, triggered mode. Source files land in /Volumes/workspace/approval_copilot/landing.
-- All local-time columns assume the session time zone is UTC (Databricks default).

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_orchestrator
COMMENT 'Raw payment intents from the orchestrator, as received.'
AS
-- Raw orchestrator files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/orchestrator/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_a
COMMENT 'Raw authorization responses from Acquirer A (ISO-8601 UTC, decimal amounts).'
AS
-- Raw acquirer_a files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_a/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_b
COMMENT 'Raw authorization responses from Acquirer B (local time + offset, minor units, R-codes).'
AS
-- Raw acquirer_b files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_b/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_c
COMMENT 'Raw authorization responses from Acquirer C (epoch millis, comma decimals, Portuguese labels).'
AS
-- Raw acquirer_c files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_c/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_merchants
COMMENT 'Merchant reference data (fictional). Grain: one row per merchant.'
AS
SELECT
  merchant_id,
  country,
  segment,
  mcc,
  CAST(avg_ticket_usd AS DOUBLE) AS avg_ticket_usd,
  CAST(concat(replace(onboarded_utc, ' ', 'T'), ':00Z') AS TIMESTAMP) AS onboarded_ts_utc
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/merchants.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_issuers
COMMENT 'Card issuer reference data (fictional issuers). Grain: one row per issuer.'
AS
SELECT
  issuer_id,
  issuer_country,
  CAST(market_share AS DOUBLE) AS market_share,
  issuer_type
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/issuers.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_acquirers
COMMENT 'Acquirers and their fees in basis points (synthetic). Grain: one row per acquirer.'
AS
SELECT
  acquirer_id,
  acquirer_name,
  countries,
  CAST(fee_bps AS INT) AS fee_bps,
  raw_format
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/acquirers.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_routing_rules
COMMENT 'Versioned routing rules: traffic share per acquirer. Grain: one row per routing version × validity period × country × card type × acquirer.'
AS
SELECT
  routing_version,
  CAST(concat(replace(valid_from_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_from_utc,
  CAST(concat(replace(valid_to_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_to_utc,
  country,
  card_type,
  scope,
  acquirer_id,
  CAST(traffic_share AS DOUBLE) AS traffic_share
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/routing_rules.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_decline_code_map
COMMENT 'Versioned map from raw acquirer status/code to canonical status, decline type and retryability. Grain: one row per mapping version × source system × raw status × raw code.'
AS
-- Versioned normalization map: (source system, raw status, raw code) -> canonical status.
-- 18 raw statuses across 4 source systems collapse into 8 canonical statuses.
SELECT
  mapping_version,
  CAST(concat(replace(valid_from_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_from_utc,
  CAST(concat(replace(valid_to_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_to_utc,
  source_system,
  raw_status,
  coalesce(raw_code, '') AS raw_code,
  nullif(iso_code, '') AS iso_code,
  reason,
  canonical_status,
  decline_type,
  CAST(retryable AS BOOLEAN) AS retryable
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/decline_code_map.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
